#include<unordered_map>
#include<algorithm> 
using namespace std;
​
int main() {
    string input;
    char keyChar;
    getline(cin, input);
    cin >> keyChar;
    unordered_map<char, int> charCount;
​
    int n = input.size();
    // 统计各个字符出现次数
    for (int i = 0; i < n; i++) {
        char c = input[i];
        charCount[c]++;
    }
​
    int res = 0;
    // 字母要注意同时统计大小写
    if ('a'<= keyChar && 'z' >= keyChar) {
        res += charCount[keyChar];
        res += charCount[keyChar - 32];
    } else if ('A'<= keyChar && 'Z' >= keyChar){
        res += charCount[keyChar];
        res += charCount[keyChar + 32];       
    } else {
        res += charCount[keyChar];
    }
​
    cout << res;
    return 0;
}

