const readline = require('readline');
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
rl.on('line', function (line) {
    lines.push(line);
    if (lines.length === 2) {
        const input = lines[0];
        const keyChar = lines[1][0];
        const charCount = {};
​
        // 统计各个字符出现次数
        for (const c of input) {
            charCount[c] = (charCount[c] || 0) + 1;
        }
​
        let res = 0;
        // 字母要注意同时统计大小写
        if (keyChar >= 'a' && keyChar <= 'z') {
            res += charCount[keyChar] || 0;
            res += charCount[keyChar.toUpperCase()] || 0;
        } else if (keyChar >= 'A' && keyChar <= 'Z') {
            res += charCount[keyChar] || 0;
            res += charCount[keyChar.toLowerCase()] || 0;
        } else {
            res += charCount[keyChar] || 0;
        }
​
        console.log(res);
        rl.close();
    }
});
